-- More medicines (2026-11-15): 19 generics, how to take them, food and medicine conflicts. Every fact is from the NHS medicine page
-- for that generic (opened and checked); no dose amounts anywhere. Conflicts NHS only implies through a general class are left out.

INSERT INTO sources (key, title, publisher, url, year, kind) VALUES
  ('nhs-losartan', jsonb_build_object('en', 'Losartan', 'bn', 'লোসার্টান'), 'NHS', 'https://www.nhs.uk/medicines/losartan/', NULL, 'patient_info'),
  ('nhs-ramipril', jsonb_build_object('en', 'Ramipril', 'bn', 'র‍্যামিপ্রিল'), 'NHS', 'https://www.nhs.uk/medicines/ramipril/how-and-when-to-take-ramipril/', NULL, 'patient_info'),
  ('nhs-bisoprolol', jsonb_build_object('en', 'Bisoprolol', 'bn', 'বিসোপ্রোলল'), 'NHS', 'https://www.nhs.uk/medicines/bisoprolol/', NULL, 'patient_info'),
  ('nhs-rosuvastatin', jsonb_build_object('en', 'Rosuvastatin', 'bn', 'রোসুভাস্ট্যাটিন'), 'NHS', 'https://www.nhs.uk/medicines/rosuvastatin/', NULL, 'patient_info'),
  ('nhs-allopurinol', jsonb_build_object('en', 'Allopurinol', 'bn', 'অ্যালোপিউরিনল'), 'NHS', 'https://www.nhs.uk/medicines/allopurinol/', NULL, 'patient_info'),
  ('nhs-colchicine', jsonb_build_object('en', 'Colchicine', 'bn', 'কলচিসিন'), 'NHS', 'https://www.nhs.uk/medicines/colchicine/', NULL, 'patient_info'),
  ('nhs-omeprazole', jsonb_build_object('en', 'Omeprazole', 'bn', 'ওমিপ্রাজল'), 'NHS', 'https://www.nhs.uk/medicines/omeprazole/', NULL, 'patient_info'),
  ('nhs-esomeprazole', jsonb_build_object('en', 'Esomeprazole', 'bn', 'ইসোমিপ্রাজল'), 'NHS', 'https://www.nhs.uk/medicines/esomeprazole/how-and-when-to-take-esomeprazole/', NULL, 'patient_info'),
  ('nhs-empagliflozin', jsonb_build_object('en', 'Empagliflozin', 'bn', 'এমপাগ্লিফ্লোজিন'), 'NHS', 'https://www.nhs.uk/medicines/empagliflozin/', NULL, 'patient_info'),
  ('nhs-sitagliptin', jsonb_build_object('en', 'Sitagliptin', 'bn', 'সিটাগ্লিপটিন'), 'NHS', 'https://www.nhs.uk/medicines/sitagliptin/', NULL, 'patient_info'),
  ('nhs-insulin', jsonb_build_object('en', 'Insulin', 'bn', 'ইনসুলিন'), 'NHS', 'https://www.nhs.uk/medicines/insulin/insulin-for-type-2-diabetes/', NULL, 'patient_info'),
  ('nhs-salbutamol', jsonb_build_object('en', 'Salbutamol inhaler', 'bn', 'সালবিউটামল'), 'NHS', 'https://www.nhs.uk/medicines/salbutamol-inhaler/how-and-when-to-use-salbutamol-inhalers/', NULL, 'patient_info'),
  ('nhs-montelukast', jsonb_build_object('en', 'Montelukast', 'bn', 'মন্টেলুকাস্ট'), 'NHS', 'https://www.nhs.uk/medicines/montelukast/how-and-when-to-take-montelukast/', NULL, 'patient_info'),
  ('nhs-sumatriptan', jsonb_build_object('en', 'Sumatriptan', 'bn', 'সুমাট্রিপটান'), 'NHS', 'https://www.nhs.uk/medicines/sumatriptan/', NULL, 'patient_info'),
  ('nhs-propranolol', jsonb_build_object('en', 'Propranolol', 'bn', 'প্রোপ্রানোলল'), 'NHS', 'https://www.nhs.uk/medicines/propranolol/how-and-when-to-take-propranolol/', NULL, 'patient_info'),
  ('nhs-carbimazole', jsonb_build_object('en', 'Carbimazole', 'bn', 'কার্বিমাজল'), 'NHS', 'https://www.nhs.uk/medicines/carbimazole/how-and-when-to-take-carbimazole/', NULL, 'patient_info'),
  ('nhs-ferrous-sulfate', jsonb_build_object('en', 'Ferrous sulfate (iron)', 'bn', 'ফেরাস সালফেট (আয়রন)'), 'NHS', 'https://www.nhs.uk/medicines/ferrous-sulfate/how-and-when-to-take-ferrous-sulfate/', NULL, 'patient_info'),
  ('nhs-melatonin', jsonb_build_object('en', 'Melatonin', 'bn', 'মেলাটোনিন'), 'NHS', 'https://www.nhs.uk/medicines/melatonin/', NULL, 'patient_info'),
  ('nhs-aspirin-low-dose', jsonb_build_object('en', 'Aspirin (low dose)', 'bn', 'অ্যাসপিরিন (কম মাত্রা)'), 'NHS', 'https://www.nhs.uk/medicines/low-dose-aspirin/', NULL, 'patient_info')
ON CONFLICT (key) DO NOTHING;

INSERT INTO medicine_generics (slug, name, group_name, food_timing, how_to_take, source_id)
SELECT pick.slug, pick.name, jsonb_build_object('en', pick.group_en, 'bn', pick.group_bn), pick.timing, jsonb_build_object('en', pick.how_en, 'bn', pick.how_bn), (SELECT id FROM sources WHERE key = pick.source)
FROM (VALUES
  ('losartan', 'Losartan', 'ARB (blood pressure)', 'এআরবি (রক্তচাপ)', 'any', 'Swallow with water, with or without food. Try to take it at the same time each day.', 'পানি দিয়ে গিলে খান, খাবারের সঙ্গে বা ছাড়া। প্রতিদিন একই সময়ে খাওয়ার চেষ্টা করুন।', 'nhs-losartan'),
  ('ramipril', 'Ramipril', 'ACE inhibitor (blood pressure)', 'এসিই ইনহিবিটর (রক্তচাপ)', 'any', 'Swallow the tablets or capsules whole with a drink of water, with or without food, at the same time every day. Your doctor may suggest taking the first dose at bedtime because it can make you dizzy.', 'ট্যাবলেট বা ক্যাপসুল পুরোটা পানি দিয়ে গিলে খান, খাবারের সঙ্গে বা ছাড়া, প্রতিদিন একই সময়ে। মাথা ঘোরাতে পারে বলে চিকিৎসক প্রথম ডোজ রাতে ঘুমানোর আগে নিতে বলতে পারেন।', 'nhs-ramipril'),
  ('bisoprolol', 'Bisoprolol', 'Beta blocker (blood pressure, heart)', 'বিটা ব্লকার (রক্তচাপ, হৃদ্‌যন্ত্র)', 'any', 'Swallow the tablets whole with a glass of water, at the same time each day, usually in the morning. Do not chew the tablets.', 'ট্যাবলেট পুরোটা এক গ্লাস পানি দিয়ে গিলে খান, প্রতিদিন একই সময়ে, সাধারণত সকালে। চিবাবেন না।', 'nhs-bisoprolol'),
  ('rosuvastatin', 'Rosuvastatin', 'Statin (cholesterol)', 'স্ট্যাটিন (কোলেস্টেরল)', 'any', 'Swallow whole with a drink of water, with or without food. Try to take it at the same time each day.', 'পুরোটা পানি দিয়ে গিলে খান, খাবারের সঙ্গে বা ছাড়া। প্রতিদিন একই সময়ে খাওয়ার চেষ্টা করুন।', 'nhs-rosuvastatin'),
  ('allopurinol', 'Allopurinol', 'Uric acid lowering (gout)', 'ইউরিক অ্যাসিড কমায় (গেঁটে বাত)', 'with_food', 'It is best taken with food; swallow tablets whole with a glass of water. Drink plenty of fluids to stay hydrated.', 'খাবারের সঙ্গে খাওয়াই ভালো; ট্যাবলেট পুরোটা এক গ্লাস পানি দিয়ে গিলে খান। শরীরে পানির ঘাটতি না রাখতে প্রচুর তরল পান করুন।', 'nhs-allopurinol'),
  ('colchicine', 'Colchicine', 'Gout treatment', 'গেঁটে বাতের চিকিৎসা', 'any', 'Swallow the tablets whole with a glass of water. Do not take doses closer together than your doctor has told you.', 'ট্যাবলেট পুরোটা এক গ্লাস পানি দিয়ে গিলে খান। চিকিৎসক যে ব্যবধান বলেছেন তার চেয়ে কাছাকাছি সময়ে ডোজ নেবেন না।', 'nhs-colchicine'),
  ('omeprazole', 'Omeprazole', 'Proton pump inhibitor (stomach acid)', 'প্রোটন পাম্প ইনহিবিটর (পাকস্থলীর অ্যাসিড)', 'any', 'Take it with or without food, at the same time each morning; swallow tablets and capsules with water. Do not chew or crush ones labelled enteric coated or gastro-resistant.', 'খাবারের সঙ্গে বা ছাড়া, প্রতিদিন সকালে একই সময়ে খান; ট্যাবলেট ও ক্যাপসুল পানি দিয়ে গিলে খান। "এন্টেরিক কোটেড" বা "গ্যাস্ট্রো-রেজিস্ট্যান্ট" লেখা হলে চিবাবেন বা গুঁড়া করবেন না।', 'nhs-omeprazole'),
  ('esomeprazole', 'Esomeprazole', 'Proton pump inhibitor (stomach acid)', 'প্রোটন পাম্প ইনহিবিটর (পাকস্থলীর অ্যাসিড)', 'any', 'Usually taken first thing in the morning, with or without food. Swallow whole with still (non-fizzy) water, not other drinks, and do not chew or crush.', 'সাধারণত সকালে প্রথমে খাওয়া হয়, খাবারের সঙ্গে বা ছাড়া। অন্য পানীয় নয়, সাধারণ (গ্যাসহীন) পানি দিয়ে পুরোটা গিলে খান; চিবাবেন বা গুঁড়া করবেন না।', 'nhs-esomeprazole'),
  ('empagliflozin', 'Empagliflozin', 'SGLT2 inhibitor (diabetes, heart, kidney)', 'এসজিএলটি২ ইনহিবিটর (ডায়াবেটিস, হৃদ্‌যন্ত্র, কিডনি)', 'any', 'Swallow the tablets whole with a drink of water, with or without food, at the same time each day. Do not stop suddenly without speaking to your doctor.', 'ট্যাবলেট পুরোটা পানি দিয়ে গিলে খান, খাবারের সঙ্গে বা ছাড়া, প্রতিদিন একই সময়ে। চিকিৎসকের সঙ্গে কথা না বলে হঠাৎ বন্ধ করবেন না।', 'nhs-empagliflozin'),
  ('sitagliptin', 'Sitagliptin', 'DPP-4 inhibitor (diabetes)', 'ডিপিপি-৪ ইনহিবিটর (ডায়াবেটিস)', 'any', 'Swallow the tablets whole with a glass of water, with or without food, at the same time each day. Do not crush or chew them.', 'ট্যাবলেট পুরোটা এক গ্লাস পানি দিয়ে গিলে খান, খাবারের সঙ্গে বা ছাড়া, প্রতিদিন একই সময়ে। গুঁড়া করবেন বা চিবাবেন না।', 'nhs-sitagliptin'),
  ('insulin', 'Insulin', 'Insulin (diabetes)', 'ইনসুলিন (ডায়াবেটিস)', 'any', 'Timing depends on the type: rapid-acting, short-acting and mixed (biphasic) insulins are taken before meals. Follow the plan from your diabetes care team.', 'সময় নির্ভর করে ধরনের ওপর: দ্রুত-কার্যকর, স্বল্প-কার্যকর ও মিশ্র ইনসুলিন খাবারের আগে নেওয়া হয়। আপনার ডায়াবেটিস চিকিৎসক দলের পরিকল্পনা মেনে চলুন।', 'nhs-insulin'),
  ('salbutamol', 'Salbutamol inhaler', 'Reliever inhaler (asthma, COPD)', 'রিলিভার ইনহেলার (অ্যাজমা, সিওপিডি)', 'any', 'Use it only when you need it, such as when you notice coughing, wheezing or breathlessness, or before an activity or trigger that makes you breathless.', 'শুধু দরকার হলে ব্যবহার করুন, যেমন কাশি, শাঁ-শাঁ শব্দ বা শ্বাসকষ্ট টের পেলে, অথবা যে কাজ বা কারণে শ্বাসকষ্ট হয় তার আগে।', 'nhs-salbutamol'),
  ('montelukast', 'Montelukast', 'Leukotriene receptor antagonist (asthma, allergy)', 'লিউকোট্রিন রিসেপ্টর অ্যান্টাগোনিস্ট (অ্যাজমা, অ্যালার্জি)', 'any', 'Most people take it once a day in the evening. Non-chewable tablets can be taken with or without food; chewable tablets should be taken on an empty stomach, away from food.', 'বেশির ভাগ মানুষ দিনে একবার, সন্ধ্যায় খান। সাধারণ ট্যাবলেট খাবারের সঙ্গে বা ছাড়া খাওয়া যায়; চিবিয়ে খাওয়ার ট্যাবলেট খালি পেটে, খাবার থেকে দূরে খেতে হয়।', 'nhs-montelukast'),
  ('sumatriptan', 'Sumatriptan', 'Triptan (migraine)', 'ট্রিপটান (মাইগ্রেন)', 'any', 'Take it as soon as possible after a migraine starts; swallow tablets whole with water, with or without food. Do not take a second dose if the first did not help.', 'মাইগ্রেন শুরু হওয়ার পর যত দ্রুত সম্ভব খান; ট্যাবলেট পুরোটা পানি দিয়ে গিলে খান, খাবারের সঙ্গে বা ছাড়া। প্রথম ডোজে কাজ না হলে দ্বিতীয় ডোজ নেবেন না।', 'nhs-sumatriptan'),
  ('propranolol', 'Propranolol', 'Beta blocker (heart, anxiety, migraine)', 'বিটা ব্লকার (হৃদ্‌যন্ত্র, উদ্বেগ, মাইগ্রেন)', 'any', 'Take it with or without food, at the same time each day; swallow tablets whole with water and do not break, chew or crush capsules.', 'খাবারের সঙ্গে বা ছাড়া, প্রতিদিন একই সময়ে খান; ট্যাবলেট পুরোটা পানি দিয়ে গিলে খান, ক্যাপসুল ভাঙবেন, চিবাবেন বা গুঁড়া করবেন না।', 'nhs-propranolol'),
  ('carbimazole', 'Carbimazole', 'Antithyroid (overactive thyroid)', 'অ্যান্টিথাইরয়েড (থাইরয়েড বেশি সক্রিয়)', 'any', 'Swallow the tablets whole with a drink of water, with or without food. Spread doses across the day as your doctor advises.', 'ট্যাবলেট পুরোটা পানি দিয়ে গিলে খান, খাবারের সঙ্গে বা ছাড়া। চিকিৎসক যেভাবে বলেন সেভাবে দিনের মধ্যে ডোজ ভাগ করুন।', 'nhs-carbimazole'),
  ('ferrous-sulfate', 'Ferrous sulfate (iron)', 'Iron supplement (anaemia)', 'আয়রন সাপ্লিমেন্ট (রক্তস্বল্পতা)', 'empty_stomach', 'Works best on an empty stomach, before or well after a meal; if it upsets your stomach you can take it with or after food. A doctor or pharmacist may suggest taking it with orange juice or vitamin C.', 'খালি পেটে সবচেয়ে ভালো কাজ করে, খাবারের আগে বা অনেক পরে; পেটে সমস্যা হলে খাবারের সঙ্গে বা পরে খাওয়া যায়। চিকিৎসক বা ফার্মাসিস্ট কমলার রস বা ভিটামিন সি-র সঙ্গে খেতে বলতে পারেন।', 'nhs-ferrous-sulfate'),
  ('melatonin', 'Melatonin', 'Sleep hormone (insomnia)', 'ঘুমের হরমোন (অনিদ্রা)', 'any', 'Take it before bedtime; swallow tablets or capsules whole with water, milk or fruit juice. Check your medicine leaflet about taking it with food.', 'ঘুমানোর আগে খান; ট্যাবলেট বা ক্যাপসুল পুরোটা পানি, দুধ বা ফলের রস দিয়ে গিলে খান। খাবারের সঙ্গে খাওয়া নিয়ে ওষুধের লিফলেট দেখে নিন।', 'nhs-melatonin'),
  ('aspirin-low-dose', 'Aspirin (low dose)', 'Antiplatelet (blood clot prevention)', 'অ্যান্টিপ্লেটলেট (রক্ত জমাট প্রতিরোধ)', 'any', 'Swallow the tablet whole with a glass of water, or dissolve dispersible tablets in water first. It is usually taken long term.', 'ট্যাবলেট পুরোটা এক গ্লাস পানি দিয়ে গিলে খান, অথবা গলে যাওয়া ট্যাবলেট আগে পানিতে গুলে নিন। সাধারণত দীর্ঘদিন খাওয়া হয়।', 'nhs-aspirin-low-dose')
) AS pick (slug, name, group_en, group_bn, timing, how_en, how_bn, source)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO medicine_food_interactions (generic_id, item, foods, severity, advice, source_id, sort)
SELECT generic.id, jsonb_build_object('en', pick.item_en, 'bn', pick.item_bn), pick.foods::jsonb, pick.severity, jsonb_build_object('en', pick.advice_en, 'bn', pick.advice_bn), (SELECT id FROM sources WHERE key = pick.source), pick.sort
FROM medicine_generics AS generic JOIN (VALUES
  ('losartan', 0, 'Grapefruit juice', 'জাম্বুরা জাতীয় গ্রেপফ্রুটের রস', '[]', 'serious', 'Avoid grapefruit juice with losartan as it can stop the medicine working properly; check with your doctor or pharmacist.', 'লোসার্টানের সঙ্গে গ্রেপফ্রুটের রস এড়িয়ে চলুন, এতে ওষুধ ঠিকমতো কাজ না-ও করতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-losartan'),
  ('losartan', 1, 'Potassium salt substitutes and supplements', 'পটাশিয়ামযুক্ত লবণের বিকল্প ও সাপ্লিমেন্ট', '[]', 'caution', 'Salt substitutes and supplements that contain potassium may not mix well with losartan; check with your doctor or pharmacist.', 'পটাশিয়ামযুক্ত লবণের বিকল্প ও সাপ্লিমেন্ট লোসার্টানের সঙ্গে না-ও মিলতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-losartan'),
  ('losartan', 2, 'Alcohol', 'অ্যালকোহল', '["alcohol"]', 'caution', 'Limit alcohol with losartan as it can raise the risk of side effects; check with your doctor or pharmacist.', 'লোসার্টানের সঙ্গে অ্যালকোহল কম রাখুন, এতে পার্শ্বপ্রতিক্রিয়ার ঝুঁকি বাড়ে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-losartan'),
  ('ramipril', 0, 'Salt substitutes (high in potassium)', 'লবণের বিকল্প (পটাশিয়াম বেশি)', '[]', 'serious', 'Do not use salt substitutes such as Lo-Salt with ramipril as they may make blood potassium too high; check with your doctor or pharmacist.', 'র‍্যামিপ্রিলের সঙ্গে "লো-সল্ট" জাতীয় লবণের বিকল্প ব্যবহার করবেন না, রক্তে পটাশিয়াম খুব বেড়ে যেতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-ramipril'),
  ('ramipril', 1, 'Alcohol', 'অ্যালকোহল', '["alcohol"]', 'caution', 'Alcohol can increase the blood-pressure-lowering effect of ramipril and make you dizzy; check with your doctor or pharmacist.', 'অ্যালকোহল র‍্যামিপ্রিলের রক্তচাপ কমানোর প্রভাব বাড়িয়ে মাথা ঘোরাতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-ramipril'),
  ('bisoprolol', 0, 'Alcohol', 'অ্যালকোহল', '["alcohol"]', 'caution', 'Alcohol with bisoprolol may increase the risk of low blood pressure; check with your doctor or pharmacist.', 'বিসোপ্রোললের সঙ্গে অ্যালকোহলে রক্তচাপ কমে যাওয়ার ঝুঁকি বাড়তে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-bisoprolol'),
  ('bisoprolol', 1, 'Fasting (not eating or drinking for long periods)', 'রোজা বা দীর্ঘ সময় না খাওয়া', '[]', 'caution', 'Fasting is not recommended with bisoprolol because it can affect blood sugar; check with your doctor or pharmacist before fasting.', 'বিসোপ্রোলল খেলে রোজা রাখা পরামর্শ দেওয়া হয় না, কারণ এটি রক্তে শর্করাকে প্রভাবিত করতে পারে; রোজার আগে চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-bisoprolol'),
  ('rosuvastatin', 0, 'Alcohol', 'অ্যালকোহল', '["alcohol"]', 'caution', 'Avoid drinking too much alcohol with rosuvastatin as it can increase the risk of side effects like liver problems; check with your doctor or pharmacist.', 'রোসুভাস্ট্যাটিনের সঙ্গে বেশি অ্যালকোহল নয়, এতে লিভারের সমস্যার মতো পার্শ্বপ্রতিক্রিয়ার ঝুঁকি বাড়ে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-rosuvastatin'),
  ('allopurinol', 0, 'Fluids', 'তরল পান', '[]', 'caution', 'Drink plenty of fluids to stay hydrated while taking allopurinol; check with your doctor or pharmacist if unsure.', 'অ্যালোপিউরিনল খাওয়ার সময় শরীরে পানির ঘাটতি না রাখতে প্রচুর তরল পান করুন; নিশ্চিত না হলে চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-allopurinol'),
  ('colchicine', 0, 'Grapefruit juice', 'জাম্বুরা জাতীয় গ্রেপফ্রুটের রস', '[]', 'serious', 'Do not drink grapefruit juice with colchicine as it can increase the amount of medicine in your blood; check with your doctor or pharmacist.', 'কলচিসিনের সঙ্গে গ্রেপফ্রুটের রস পান করবেন না, এতে রক্তে ওষুধের পরিমাণ বেড়ে যেতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-colchicine'),
  ('omeprazole', 0, 'Alcohol', 'অ্যালকোহল', '["alcohol"]', 'caution', 'It is best not to drink alcohol with omeprazole as it can increase stomach acid and worsen symptoms; check with your doctor or pharmacist.', 'ওমিপ্রাজলের সঙ্গে অ্যালকোহল না খাওয়াই ভালো, এতে পাকস্থলীর অ্যাসিড বেড়ে উপসর্গ বাড়তে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-omeprazole'),
  ('esomeprazole', 0, 'Alcohol', 'অ্যালকোহল', '["alcohol"]', 'caution', 'Alcohol makes the stomach produce more acid and can worsen symptoms while on esomeprazole; check with your doctor or pharmacist.', 'অ্যালকোহল পাকস্থলীতে বেশি অ্যাসিড তৈরি করে এবং ইসোমিপ্রাজল চলার সময় উপসর্গ বাড়াতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-esomeprazole'),
  ('esomeprazole', 1, 'Caffeinated drinks', 'ক্যাফেইনযুক্ত পানীয়', '["black-tea", "coffee", "milk-tea", "soft-drinks"]', 'caution', 'Try to cut down on tea, coffee and cola if they worsen your symptoms; check with your doctor or pharmacist.', 'চা, কফি ও কোলায় উপসর্গ বাড়লে এগুলো কমানোর চেষ্টা করুন; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-esomeprazole'),
  ('esomeprazole', 2, 'Rich, spicy, fatty and acidic foods', 'ভারী, ঝাল, তেল-চর্বিযুক্ত ও টক খাবার', '["green-chili", "lemon", "orange", "soft-drinks", "tomato"]', 'caution', 'Avoid foods that seem to make your indigestion worse, such as rich, spicy, fatty or acidic foods; check with your doctor or pharmacist.', 'যেসব খাবারে বদহজম বাড়ে বলে মনে হয়, যেমন ভারী, ঝাল, তেল-চর্বিযুক্ত বা টক খাবার, সেগুলো এড়িয়ে চলুন; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-esomeprazole'),
  ('empagliflozin', 0, 'Alcohol', 'অ্যালকোহল', '["alcohol"]', 'caution', 'Limit alcohol with empagliflozin as it can raise the risk of side effects such as diabetic ketoacidosis; check with your doctor or pharmacist.', 'এমপাগ্লিফ্লোজিনের সঙ্গে অ্যালকোহল কম রাখুন, এতে ডায়াবেটিক কিটোঅ্যাসিডোসিসের মতো পার্শ্বপ্রতিক্রিয়ার ঝুঁকি বাড়ে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-empagliflozin'),
  ('sitagliptin', 0, 'Alcohol', 'অ্যালকোহল', '["alcohol"]', 'caution', 'It is best not to drink alcohol with sitagliptin as it can affect your blood sugar; check with your doctor or pharmacist.', 'সিটাগ্লিপটিনের সঙ্গে অ্যালকোহল না খাওয়াই ভালো, এতে রক্তে শর্করা প্রভাবিত হতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-sitagliptin'),
  ('sitagliptin', 1, 'Skipping or delaying meals', 'খাবার বাদ দেওয়া বা দেরিতে খাওয়া', '[]', 'caution', 'Do not skip or delay meals while taking sitagliptin as part of diabetes treatment; check with your doctor or pharmacist.', 'ডায়াবেটিসের চিকিৎসায় সিটাগ্লিপটিন খাওয়ার সময় খাবার বাদ দেবেন না বা দেরি করবেন না; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-sitagliptin'),
  ('propranolol', 0, 'Alcohol', 'অ্যালকোহল', '["alcohol"]', 'caution', 'Alcohol can increase the blood-pressure-lowering effect of propranolol and make you dizzy; check with your doctor or pharmacist.', 'অ্যালকোহল প্রোপ্রানোললের রক্তচাপ কমানোর প্রভাব বাড়িয়ে মাথা ঘোরাতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-propranolol'),
  ('carbimazole', 0, 'Iodine-rich foods', 'আয়োডিন বেশি এমন খাবার', '["cheese", "egg", "instant-noodles", "iodized-salt", "sausage"]', 'caution', 'Foods high in iodine can make symptoms worse and your doctor may suggest a low-iodine diet; check with your doctor or pharmacist.', 'আয়োডিন বেশি এমন খাবার উপসর্গ বাড়াতে পারে এবং চিকিৎসক কম-আয়োডিনের খাবার পরামর্শ দিতে পারেন; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-carbimazole'),
  ('carbimazole', 1, 'Alcohol and caffeine (if dizzy)', 'অ্যালকোহল ও ক্যাফেইন (মাথা ঘোরালে)', '["alcohol", "black-tea", "coffee", "milk-tea"]', 'caution', 'If carbimazole makes you dizzy, avoid alcohol, coffee and other caffeinated drinks as they can make it worse; check with your doctor or pharmacist.', 'কার্বিমাজলে মাথা ঘোরালে অ্যালকোহল, কফি ও অন্য ক্যাফেইনযুক্ত পানীয় এড়িয়ে চলুন, এগুলো তা বাড়াতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-carbimazole'),
  ('ferrous-sulfate', 0, 'Tea, coffee, eggs and dairy', 'চা, কফি, ডিম ও দুগ্ধজাত খাবার', '["black-tea", "cheese", "coffee", "doi", "egg", "milk", "milk-tea", "powdered-milk"]', 'serious', 'Do not take iron tablets with tea, coffee, eggs or dairy as they reduce iron absorption; leave a gap and check with your doctor or pharmacist.', 'আয়রন ট্যাবলেট চা, কফি, ডিম বা দুগ্ধজাত খাবারের সঙ্গে খাবেন না, এগুলো আয়রন শোষণ কমায়; সময়ের ব্যবধান রাখুন এবং চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-ferrous-sulfate'),
  ('ferrous-sulfate', 1, 'Calcium, magnesium or zinc supplements and antacids', 'ক্যালসিয়াম, ম্যাগনেসিয়াম বা জিঙ্ক সাপ্লিমেন্ট ও অ্যান্টাসিড', '[]', 'caution', 'Calcium and some supplements or antacids can reduce the effect of iron tablets; check with your doctor or pharmacist about spacing them.', 'ক্যালসিয়াম এবং কিছু সাপ্লিমেন্ট বা অ্যান্টাসিড আয়রন ট্যাবলেটের কার্যকারিতা কমাতে পারে; কতটা ব্যবধানে খাবেন তা চিকিৎসক বা ফার্মাসিস্টের কাছে জেনে নিন।', 'nhs-ferrous-sulfate'),
  ('melatonin', 0, 'Alcohol', 'অ্যালকোহল', '["alcohol"]', 'serious', 'Try to avoid alcohol with melatonin as it can stop the medicine working properly; check with your doctor or pharmacist.', 'মেলাটোনিনের সঙ্গে অ্যালকোহল এড়িয়ে চলার চেষ্টা করুন, এতে ওষুধ ঠিকমতো কাজ না-ও করতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-melatonin'),
  ('aspirin-low-dose', 0, 'Alcohol', 'অ্যালকোহল', '["alcohol"]', 'caution', 'Limit alcohol with aspirin as it can increase the risk of side effects; check with your doctor or pharmacist.', 'অ্যাসপিরিনের সঙ্গে অ্যালকোহল কম রাখুন, এতে পার্শ্বপ্রতিক্রিয়ার ঝুঁকি বাড়ে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-aspirin-low-dose')
) AS pick (slug, sort, item_en, item_bn, foods, severity, advice_en, advice_bn, source) ON pick.slug = generic.slug
WHERE NOT EXISTS (SELECT 1 FROM medicine_food_interactions m WHERE m.generic_id = generic.id AND m.sort = pick.sort);

INSERT INTO medicine_interactions (first_id, second_id, severity, reason, source_id)
SELECT LEAST(a.id, b.id), GREATEST(a.id, b.id), pick.severity, jsonb_build_object('en', pick.reason_en, 'bn', pick.reason_bn), (SELECT id FROM sources WHERE key = pick.source)
FROM (VALUES
  ('ramipril', 'allopurinol', 'caution', 'Both the ramipril and allopurinol NHS pages list each other (ACE inhibitors / allopurinol) as medicines to mention to your doctor; check with your doctor or pharmacist.', 'এনএইচএস জানায় র‍্যামিপ্রিল ও অ্যালোপিউরিনল একসঙ্গে ঠিকমতো না-ও মিলতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-ramipril'),
  ('colchicine', 'simvastatin', 'caution', 'NHS lists statins as medicines that may not mix well with colchicine; check with your doctor or pharmacist.', 'এনএইচএস জানায় কলচিসিন ও simvastatin একসঙ্গে ঠিকমতো না-ও মিলতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-colchicine'),
  ('colchicine', 'atorvastatin', 'caution', 'NHS lists statins as medicines that may not mix well with colchicine; check with your doctor or pharmacist.', 'এনএইচএস জানায় কলচিসিন ও atorvastatin একসঙ্গে ঠিকমতো না-ও মিলতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-colchicine'),
  ('colchicine', 'rosuvastatin', 'caution', 'NHS lists statins as medicines that may not mix well with colchicine; check with your doctor or pharmacist.', 'এনএইচএস জানায় কলচিসিন ও রোসুভাস্ট্যাটিন একসঙ্গে ঠিকমতো না-ও মিলতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-colchicine'),
  ('rosuvastatin', 'warfarin', 'caution', 'NHS lists warfarin as a medicine that may not mix well with rosuvastatin; check with your doctor or pharmacist.', 'এনএইচএস জানায় রোসুভাস্ট্যাটিন ও warfarin একসঙ্গে ঠিকমতো না-ও মিলতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-rosuvastatin'),
