  ('melatonin', 'warfarin', 'caution', 'NHS lists warfarin as a medicine that may not mix well with melatonin; check with your doctor or pharmacist.', 'এনএইচএস জানায় মেলাটোনিন ও warfarin একসঙ্গে ঠিকমতো না-ও মিলতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-melatonin'),
  ('aspirin-low-dose', 'warfarin', 'caution', 'Aspirin and anticoagulants such as warfarin may not mix well, as both NHS pages state; check with your doctor or pharmacist.', 'এনএইচএস জানায় অ্যাসপিরিন (কম মাত্রা) ও warfarin একসঙ্গে ঠিকমতো না-ও মিলতে পারে; চিকিৎসক বা ফার্মাসিস্টের সঙ্গে কথা বলুন।', 'nhs-aspirin-low-dose')
) AS pick (first_slug, second_slug, severity, reason_en, reason_bn, source)
JOIN medicine_generics a ON a.slug = pick.first_slug JOIN medicine_generics b ON b.slug = pick.second_slug
WHERE NOT EXISTS (SELECT 1 FROM medicine_interactions m WHERE (m.first_id = a.id AND m.second_id = b.id) OR (m.first_id = b.id AND m.second_id = a.id));
